quote['address_line2'],'city'=>$quote['city'],'state'=>$quote['state'],'landmark'=>$quote['landmark']];$paymentStatus=$paymentMethod==='cod'?'cod_pending':'pending';$orderStatus=$paymentMethod==='cod'?'confirmed':'payment_pending';$db->prepare('INSERT INTO orders (user_id,checkout_quote_id,order_number,status,payment_status,currency,subtotal,shipping_amount,discount_amount,tax_amount,total_amount,address_snapshot_json,placed_at,created_at,updated_at) VALUES (:user,:quote,:number,:status,:payment,"INR",:subtotal,:shipping,:discount,:tax,:total,:address,UTC_TIMESTAMP(),UTC_TIMESTAMP(),UTC_TIMESTAMP())')->execute(['user'=>$principal['id'],'quote'=>$quoteId,'number'=>$number,'status'=>$orderStatus,'payment'=>$paymentStatus,'subtotal'=>$quote['subtotal'],'shipping'=>$quote['shipping_amount'],'discount'=>$quote['discount_amount'],'tax'=>$quote['tax_amount'],'total'=>$quote['total_amount'],'address'=>json_encode($addressSnapshot,JSON_UNESCAPED_SLASHES)]);$orderId=(int)$db->lastInsertId();$vendorGroups=[];foreach($cart['items'] as $item)$vendorGroups[$item['vendor_id']][]=$item;$itemSubtotal=(float)$quote['subtotal'];foreach($vendorGroups as $vendorId=>$items){$groupSubtotal=array_sum(array_column($items,'line_subtotal'));$ratio=$itemSubtotal>0?$groupSubtotal/$itemSubtotal:0;$groupShipping=(float)($pricing['groups'][$vendorId]['shipping']??0);$groupDiscount=round((float)$quote['discount_amount']*$ratio,2);$groupTax=0.0;foreach($items as $item)$groupTax+=round($item['line_subtotal']*((float)$item['gst_percent']/100),2);$groupTotal=round($groupSubtotal+$groupShipping+$groupTax-$groupDiscount,2);$groupId=uuid_string();$groupNumber=$number.'-'.str_pad((string)(count($vendorGroups)>1?count($vendorGroups):1),2,'0',STR_PAD_LEFT).'-'.strtoupper(substr($vendorId,0,4));$policy=$db->prepare('SELECT return_policy,cancellation_policy,damage_policy,handmade_policy FROM vendor_settings WHERE vendor_id=:vendor');$policy->execute(['vendor'=>$vendorId]);$policySnapshot=$policy->fetch()?:['re