iant_id=:variant')->execute(['quote'=>$quoteId,'variant'=>$item['variant_id']]);$db->prepare('INSERT INTO inventory_movements (variant_id,vendor_id,movement_type,quantity_delta,reserved_delta,stock_after,reserved_after,reference_type,reference_id,note,actor_type,actor_id,created_at) SELECT :variant,:vendor,"sale",-:qty,-:qty,stock_quantity,reserved_quantity,"order_item",:reference,"Order placed","customer",:actor,UTC_TIMESTAMP() FROM inventory_levels WHERE variant_id=:variant')->execute(['variant'=>$item['variant_id'],'vendor'=>$vendorId,'qty'=>$item['quantity'],'reference'=>(string)$orderItemId,'actor'=>$principal['id']]);$db->prepare('INSERT INTO vendor_ledger_entries (id,vendor_id,entry_type,amount,currency,balance_bucket,reference_type,reference_id,description,available_at,created_at) VALUES (:id,:vendor,"order_earning",:amount,"INR","pending","order_item",:reference,"Order earning pending delivery",DATE_ADD(UTC_TIMESTAMP(),INTERVAL 7 DAY),UTC_TIMESTAMP())')->execute(['id'=>uuid_string(),'vendor'=>$vendorId,'amount'=>$net,'reference'=>(string)$orderItemId]);}}if($paymentMethod==='cod')$db->prepare('INSERT INTO cod_collections (id,order_id,vendor_group_id,vendor_id,amount,status,created_at,updated_at) VALUES (:id,:order,:group,:vendor,:amount,"pending",UTC_TIMESTAMP(),UTC_TIMESTAMP())')->execute(['id'=>uuid_string(),'order'=>$orderId,'group'=>$groupId,'vendor'=>$vendorId,'amount'=>$groupTotal]);create_notification('vendor',$vendorId,'new_order','New order received','A new order is waiting for your acceptance.','../orders.php',['order_id'=>$orderId,'group_id'=>$groupId]);}$db->prepare('UPDATE checkout_quotes SET status="converted" WHERE id=:id')->execute(['id'=>$quoteId]);$db->prepare('UPDATE carts SET status="converted",updated_at=UTC_TIMESTAMP() WHERE id=:id')->execute(['id'=>$cart['id']]);if($quote['coupon_id']!==null)$db->prepare('INSERT INTO coupon_redemptions (id,coupon_id,user_id,order_id,discount_amount,created_at) VALUES (:id,:coupon,:user,:order,:amount,UTC_TIMESTAMP())')->execute(['id'=>uuid_string(),'coupon'=>$quote['coupon_id'],'user'=>$principal['id'],'order'=>$orderId,'amount'=>$quote['discount_amount']]);$paymentId=uuid_string();$db->prepare('INSERT INTO payment_attempts (id,order_id,provider,amount,currency,status,created_at) VALUES (:id,:order,:provider,:amount,"INR",:status,UTC_TIMESTAMP())')->execute(['id'=>$paymentId,'order'=>$orderId,'provider'=>$paymentMethod,'amount'=>$quote['total_amount'],'status'=>$paymentMethod==='cod'?'cod_pending':'created']);record_status_change('order',(string)$orderId,null,$orderStatus);attribute_influencer_order($orderId,$principal['id'],(float)$quote['total_amount']);audit_event('customer.order_placed','order',(string)$orderId,['order_number'=>$number,'payment_method'=>$paymentMethod]);$response=['success'=>true,'message'=>$paymentMethod==='cod'?'Order placed successfully.':'Order created. Continue to the payment provider.','order'=>['id'=>$orderId,'order_number'=>$number,'status'=>$orderStatus,'payment_status'=>$paymentStatus,'total_amount'=>(float)$quote['total_amount']],'payment'=>['attempt_id'=>$paymentId,'provider'=>$paymentMethod,'status'=>$paymentMethod==='cod'?'cod_pending':'created']];finish_idempotent_request((int)$idem['id'],201,$response);$db->commit();json_response(201,$response);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
